const DEF_TO=[];
function tableHTML(d,opt){opt=opt||{};const bw=!!opt.bw;const week=d==='wk';const rows=rowsFor(d);const F='font-family:Calibri,Arial,sans-serif;';
  const hd=bw?'#000000':'#5e2a21',fmCol=bw?'#000000':'#c25a0e';
  const th=`${F}background:${hd};color:#ffffff;font-size:12px;font-weight:700;padding:7px 8px;text-align:left;border:1px solid ${hd};white-space:nowrap`;
  const td=`${F}font-size:12px;color:#222222;padding:6px 8px;border:1px solid ${bw?'#999999':'#d9d0c7'};vertical-align:top`;
  let wm=null;if(week){wm={};const mon0=monOf(date);for(let i=0;i<7;i++){const dd2=addD(mon0,i);for(const rr of rowsFor(dd2)){for(const c of rr.crew){if(offOn(c.n,dd2))continue;(wm[c.n]=wm[c.n]||{})[i]=rr.s._id}}}}
  const mon0=monOf(date);
  const fmtDays=idxs=>{idxs=[...idxs].sort((a,b)=>a-b);const o=[];let i=0;while(i<idxs.length){let j=i;while(j+1<idxs.length&&idxs[j+1]===idxs[j]+1)j++;o.push(i===j?DOWN[idxs[i]]:DOWN[idxs[i]]+'–'+DOWN[idxs[j]]);i=j+1}return o.join(', ')};
  let pSites=null,pTag=null;if(week){pSites={};pTag={};for(let i=0;i<7;i++){const dd2=addD(mon0,i);for(const rr of rowsFor(dd2)){for(const c of rr.crew){if(offOn(c.n,dd2))continue;(pSites[c.n]=pSites[c.n]||new Set()).add(rr.s._id);if(c.t&&!pTag[c.n])pTag[c.n]=c.t}}}}
  const weekCrew=sid=>{const out=[];for(const n in (wm||{})){const ds=[];for(let i=0;i<7;i++)if(wm[n][i]===sid)ds.push(i);if(ds.length)out.push({n,days:ds})}return out.sort((a,b)=>lvRank(lvOf(a.n))-lvRank(lvOf(b.n))||short(a.n).localeCompare(short(b.n)))};
  const offDays=n=>{const o=[];for(let i=0;i<7;i++)if(offOn(n,addD(mon0,i)))o.push(DOWN[i]);return o};
  const nmDay=c=>{const l=lvOf(c.n);const fm=['FM','SFM'].includes(l);return `<div style="${F}font-size:12px;line-height:1.55">${c.t?`<span style="color:#888888;font-size:11px">${E(c.t)}</span> `:''}<span style="${fm?`font-weight:700;color:${fmCol}`:''}">${E(short(c.n))}</span><span style="color:#888888">_${E(l||'')}</span></div>`};
  const nmWeek=x=>{const l=lvOf(x.n);const fm=['FM','SFM'].includes(l);const split=pSites&&pSites[x.n]&&pSites[x.n].size>1;const offd=offDays(x.n);const notes=[];if(split)notes.push(fmtDays(x.days));if(offd.length)notes.push('off '+offd.join(', '));const t=pTag&&pTag[x.n];
    return `<div style="${F}font-size:12px;line-height:1.55">${t?`<span style="color:#888888;font-size:11px">${E(t)}</span> `:''}<span style="${fm?`font-weight:700;color:${fmCol}`:''}">${E(short(x.n))}</span><span style="color:#888888">_${E(l||'')}</span>${notes.length?` <span style="color:${bw?'#555555':'#c25a0e'};font-size:10px">(${E(notes.join(' · '))})</span>`:''}</div>`};
  const body=rows.map((r,k)=>{const s=r.s;const crew=week?weekCrew(s._id):r.crew.filter(c=>!offOn(c.n,d));const render=week?nmWeek:nmDay;const pc=(!bw&&s.pic)?picCol(s.pic):'';const bg=bw?(k%2?'#f0f0f0':'#ffffff'):(k%2?'#faf7f4':'#ffffff');return `<tr style="background:${bg}">
    <td style="${td};width:30%"><b style="font-size:13px">${E(jno(s.no))}</b> <span style="font-size:13px">${E(s.name||'')}</span></td>
    <td style="${td};width:13%">${E(s.sys||'')}</td>
    <td style="${td};width:9%;${pc?`background:${pc};color:#ffffff;font-weight:700`:'font-weight:700'};white-space:nowrap">${E(s.pic||'')}</td>
    <td style="${td};width:4%;text-align:center;${s.isNew?(bw?'font-weight:800;border:2px solid #000000':'background:#ffe600;font-weight:700'):''}">${s.isNew?'Y':'N'}</td>
    <td style="${td};width:4%;text-align:center;font-weight:700">${crew.length}</td>
    <td style="${td}">${r.note?`<div style="${F}font-size:12px;color:${bw?'#000000':'#1f5fbf'};margin-bottom:3px">** ${E(r.note)}</div>`:''}${crew.length>6?(()=>{const h=Math.ceil(crew.length/2);return `<table class="dsin" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr><td style="vertical-align:top;padding:0 18px 0 0;border:0">${crew.slice(0,h).map(render).join('')}</td><td style="vertical-align:top;padding:0;border:0">${crew.slice(h).map(render).join('')}</td></tr></table>`})():(crew.map(render).join('')||'<span style="color:#999999">—</span>')}</td></tr>`}).join('');
  const off=offList(d);
  return `<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;max-width:900px"><tr><th style="${th}">Task Name</th><th style="${th}">Roof System</th><th style="${th}">PIC</th><th style="${th};text-align:center">New</th><th style="${th};text-align:center">Crew</th><th style="${th}">Resource Names</th></tr>${body}${off.length?`<tr><td colspan="5" style="${td};font-weight:700;${bw?'':'background:#fdecea;color:#b3261e'}">Time off</td><td style="${td};${bw?'':'background:#fdecea'}">${off.map(l=>`<div style="${F}font-size:12px;line-height:1.55">${E(short(l.n))} <span style="color:${bw?'#000000':'#b3261e'}">(${E(l.type||'Off')}${l.from?' '+E(fmtD(l.from))+(l.to&&l.to!==l.from?'–'+E(fmtD(l.to)):''):''})</span></div>`).join('')}</td></tr>`:''}</table>
  <div style="${F}font-size:11px;color:#888888;margin-top:6px"><b style="color:${fmCol}">Foreman</b> &nbsp;·&nbsp; ${rows.length} jobs · ${week?Object.keys(wm||{}).length:rows.reduce((a,r)=>a+r.crew.filter(c=>!offOn(c.n,d)).length,0)} people</div>`}
const LOGO_URL='https://app.amebuilders.net/logo.png';
