  const tabs=`<div class="viewseg" style="margin-bottom:10px">${[['matrix','Skill set'],['cert','Certifications'+(soon.length?` <b class="skbadge">${soon.length}</b>`:'')],['rate','Ratings'],['score','Score & priority']].map(([k,l])=>`<button data-skt="${k}" aria-pressed="${skTab===k}">${l}</button>`).join('')}</div>`;
  const filt=`<div class="stsort"><input id="skQ" class="search" placeholder="Search name or #" value="${E(skQ)}"><label class="muted">Level<select id="skLv"><option value="">All</option><option value="FM">FM / SFM</option><option value="JM">JM</option><option value="A">Apprentices</option></select></label>`;
