async function snapScores(P,why){const at=new Date().toISOString();const m={};P.forEach(p=>{const s=scoreOf(p);m['s'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)]={n:p.name,at,by:curUser,sc:s.sc,pr:s.pr,prNow:String(p.pr||''),part:s.part,dw:s.dw,yrs:s.yrs,ra:s.ra,certs:s.certs,why:why||'snapshot'}});if(db.setMany)await db.setMany('dscore',m);else for(const k in m)await db.doc('dscore/'+k).set(m[k])}
