/* ---- one person's certificates on one page; tap a date to open the actual certificate ---- */
async function openCert(path){const w=window.open('','_blank');try{const fs=await window.claude.use('files');const bl=await fs.read(path);const u=URL.createObjectURL(bl);if(w)w.location=u;else window.open(u,'_blank')}catch(e){if(w)w.close();toast('Could not open: '+(e.message||e))}}
