/* NEW lasts 2 weeks from when it was turned on, then turns itself off */
const NEW_DAYS=14;let newChk=0;
function newExpire(){const now=Date.now();S.forEach(x=>{if(!x.isNew)return;if(!x.newAt){if(typeof isEditor==='function'&&!isEditor(curUser))return;if(now-newChk<5000)return;x.newAt=new Date().toISOString();db.doc('dsites/'+x._id).update({newAt:x.newAt}).catch(()=>{});return}
  const age=now-new Date(x.newAt).getTime();if(age>NEW_DAYS*864e5){x.isNew=false;db.doc('dsites/'+x._id).update({isNew:false,newAt:null,newEnded:new Date().toISOString()}).catch(()=>{})}});newChk=now}
