/* crew size check: people come and go by date, so compare the plan with the most people on the job at the same time */
function peakCrew(s,fallback){const A=(s.asg||[]).filter(a=>a&&a.n);if(!A.length)return fallback;const ev=[];A.forEach(a=>{const f=a.from||'0000',t=a.to||'9999';ev.push([f,1],[t+'~',-1])});ev.sort((x,y)=>x[0]<y[0]?-1:x[0]>y[0]?1:y[1]-x[1]);let c=0,m=0;ev.forEach(e=>{c+=e[1];if(c>m)m=c});return m}
